PAIRS_PER_CATEGORY = 276
TOTAL_QUESTIONS = len(CATEGORIES) * PAIRS_PER_CATEGORY

def get_question(index):
    if not 0 <= index < TOTAL_QUESTIONS:
        raise ValueError("Invalid question index")
    category_index, pair_index = divmod(index, PAIRS_PER_CATEGORY)
    category, choices = list(CATEGORIES.items())[category_index]
    left, right = next(pair for i, pair in enumerate(combinations(choices,2)) if i == pair_index)
    return {"id": f"TOT-{index:05d}", "category": category,
            "question": f"{category} — ဘယ်ဟာကို ပိုကြိုက်လဲ?",
            "options": (left, right),
            "visual_tags": (f"{category}/{left}", f"{category}/{right}")}

def validate_bank():
    seen=set()
    for i in range(TOTAL_QUESTIONS):
        q=get_question(i)
        assert q["id"] not in seen
        assert len(q["options"])==2 and q["options"][0]!=q["options"][1]
        assert all(len(x)<=100 for x in q["options"])
        assert len(q["question"])<=300
        seen.add(q["id"])
    return len(seen)
